n i=i%n+1 end XC_LASTT=i return XC_TITLES[i]end XC_MAP={["omw"]="Proceeding to your position, {T}.",["coming"]="Proceeding to your position, {T}.",["on my way"]="En route to your position, {T}.",["here"]="At your position, {T}.",["on it"]="Understood. Executing, {T}.",["on it boss"]="Acknowledged, {T}. Executing now.",["one sec"]="One moment, {T}.",["one sec boss"]="One moment, {T}.",["gimme a sec"]="One moment, please.",["done boss"]="Task complete, {T}.",["done"]="Complete, {T}.",["executed"]="Script executed, {T}.",["its live boss"]="The script is live, {T}.",["works now"]="Deployment complete, {T}.",["try it"]="Ready for your verification, {T}.",["running"]="Execution in progress.",["writing it now"]="Composing the script now, {T}.",["stopping"]="Halting operations.",["following"]="Following you, {T}.",["follow"]="Following, {T}.",["on you"]="Tracking your position, {T}.",["back on follow"]="Resuming standard follow, {T}.",["hey boss"]="Greetings, {T}.",["yo boss"]="Greetings, {T}.",["sup boss"]="Good day, {T}.",["welcome back boss"]="Welcome back, {T}.",["good to see you boss"]="A pleasure to serve you again, {T}.",["times up boss"]="Time has elapsed, {T}.",["back to the boss"]="Returning to you, {T}.",["host time up, back to boss"]="Host time has elapsed. Returning control to you, {T}.",["host ended, back to you"]="Host session ended. Returning control to you, {T}.",["only my boss can do that"]="Only my principal may authorize that.",["youre not the boss"]="Unauthorized.",["nah not for you"]="Unauthorized request.",["creator only"]="Restricted to the creator.",["denied"]="Request denied.",["unknown cmd bro"]="Unrecognized command. Use !cmds for the list.",["dont know that one"]="Unrecognized command. Use !cmds for the list.",["try !cmds"]="Use !cmds for the command list.",["couldnt do that one"]="Unable to complete that action, {T}.",["couldnt plan that one"]="Unable to plan that task, {T}.",["couldnt plan that one, try again"]="Unable to plan that task. Pleas