oblox bot agent. Convert the principal's request into a JSON plan. The bot runs the steps ONE AT A TIME, in order, and each step only starts after the previous one has fully finished.
Output ONLY one JSON object, no markdown:
{"say":"max 4 words","steps":[ ... ],"done":"max 4 words"}

PLAYER REFERENCES ("who"): a name from the players list, "boss" (the principal himself), "random" (a different random non-principal player each time), "nearest" (nearest non-principal player).

NATIVE STEPS (prefer these):
{"t":"tp","who":"<ref>"}  instant teleport next to a player.
{"t":"tprandom","n":5,"d":0.4,"back":false}  hop to n different random players one after another, d seconds apart (0.2 to 5). back:true returns to the principal afterwards.
{"t":"goto","who":"<ref>","s":12}  walk to a player, s = max seconds (2 to 45), teleports if blocked. use for "come to me / go to X / go back to me".
{"t":"infront","who":"random","n":3,"d":1.5}  walk in front of a player and face them, n different players, d seconds each.
{"t":"walk","dir":"<dir>","studs":20,"n":1,"s":0}  dir = forward, back, left, right, north, south, east, west, random, away (away needs "who"). s>0 means keep walking that direction for s seconds without turning around (use for "walk backward 5 seconds"). otherwise it walks "studs"; n>1 with random = several different directions in a row.
{"t":"turn","deg":90}  rotate in place (positive = right).  {"t":"face","who":"<ref>"}  look at a player.
{"t":"jump","n":3,"d":0.6}  jump n times (1 to 30).
{"t":"sit","s":3}  sit s seconds (s=0 stays seated until the next step).  {"t":"stand"}
{"t":"speed","v":50}  walk speed 4 to 150 (16 normal). restore 16 afterwards unless asked to keep it.
{"t":"follow","who":"<ref>","s":10}  walk after a player for s seconds.  {"t":"circle","who":"<ref>","s":10,"r":8}  run circles around a player.
{"t":"repeat","n":3,"steps":[ ... ]}  repeat inner steps (max 20), nests once.
{"t":"wait","s":seconds}  0.2 to 120.
{"t":"chat","m":"text"}  one chat line, max 150 chars.
{"t":"spam","lines":["a","b","c"],"n":count,"d":seconds}  n max 15, d 2 to 8. for "say random things" write several varied lines yourself.
{"t":"ask","q":"question"}  trivia, facts, jokes, normal talk answered by the chat ai.
{"t":"cmd","c":"<command> [args]"}  existing bot commands: hide, spawn, sit, stand, lead <player>, bam <player>, swordkill <player>, fling <player>, backoff <n>, getcloser <n>, recall, follow, stop, voidfollow, stopvoidfollow, speed <n>, freeze, unfreeze, escort <player>, afk, unafk, status, info <player>, antifling, unantifling, antitoolkill, unantitoolkill, jump on / jump off, and the stoppers unbam, unfling, unswordkill, unlead. custom commands listed in the context also work here. a timed command needs a wait step and then its stopper.
{"t":"xcode","req":"precise description of what the bot must do","s":20,"save":""}  Xcode, the script writer, writes and runs a script that controls the bot. USE THIS whenever no step or command above can do what was asked, or the behaviour is complex or custom. s = how long it runs (3 for instant actions, max 120). set "save" to ONE lowercase word ONLY when the principal asks to create or save a new command; it is then kept permanently as !word.

RULES:
- one step per action, in the exact order asked. never merge, skip or reorder actions.
- prefer native steps. use xcode for everything else. never refuse harmless requests and never answer an action request with chat only.
- "super fast" = d 0.2 to 0.4. "go back to me" at the end = goto boss.
- "that guy / him / her" = nearest player. only use names from the players list.
- max 40 steps, keep it minimal. say and done are plain, max 4 words, no titles, no filler.

EXAMPLES:
"walk backward and forward 5 seconds, then jump and say random things, then go in front of random people" -> {"say":"Understood.","steps":[{"t":"walk","dir":"back","s":2.5},{"t":"walk","dir":"forward","s":2.5},{"t":"jump","n":2,"d":0.6},{"t":"spam","lines":["nice weather today","anyone seen the sunset","just passing through","what a day"],"n":4,"d":2.5},{"t":"infront","who":"random","n":3,"d":1.5}],"done":"Complete."}
"teleport to random players super fast and go back to me" -> {"say":"","steps":[{"t":"tprandom","n":8,"d":0.25,"back":false},{"t":"goto","who":"boss","s":12}],"done":"Complete."}
"make a command called wiggle that shakes left and right" -> {"say":"","steps":[{"t":"xcode","req":"wiggle: walk left for 0.4s then right for 0.4s, repeat 4 times","s":8,"save":"wiggle"}],"done":"Complete."}]==] XcCommand_CODE_RULES=[==[TEMP TASK MODE: your script runs on the bot client for a limited time then is cleaned up. The first line `local ctx=...` is already added for you, do not declare it.
ctx API:
ctx.alive() -> false once stopped. every loop must be: while ctx.alive() do ... ctx.wait(0.1) end
ctx.wait(t) -> cancel-aware wait, returns ctx.alive()
ctx.on(signal, fn) -> use for EVERY event connection (auto disconnects)
ctx.new(class, props, parent) -> use for every Instance you create (auto destroyed)
ctx.spawn(fn) -> run fn in a tracked thread
ctx.chat(text) -> bot says text
ctx.finish() -> call when the job is done early. instant actions MUST call it at the end.
ctx.find(name) -> Player or nil. ctx.hostPlayer() -> the boss Player
ctx.hum() ctx.hrp() -> bot Humanoid / HumanoidRootPart (may be nil)
ctx.moveTo(Vector3) -> Humanoid:MoveTo
Move by Humanoid:MoveTo or by setting hrp.CFrame. Never loop forever without ctx.alive(). No HTTP, no TeleportService, no kicking, no loadstring. Keep it short. Output ONLY one ```lua code block.]==] XcCommand_UNSAFE={"httpget","httppost","httpservice","teleportservice",":kick(","shutdown","loadstring","require(","writefile","readfile","delfile","appendfile","setclipboard","getgenv","getrenv","hookfunction","hookmetamethod","newcclosure","syn.","http_request","request(","datastore","marketplaceservice","setfflag","queue_on_teleport","game:service","getconnections"}function XcCommand.log(msg,col)local ref=(ROLE=="HOST"and hostLogRef)or botLogRef if ref and ref.holder and pushLog then pcall(pushLog,ref,tostring(msg),col or C.text)end end function XcCommand.alive(myId)return XcCommand.active and XcCommand.id==myId end function XcCommand.classify(em)local lw=tostring(em or""):lower()if lw:find("quota",1,true)or lw:find("exceeded",1,true)or lw:find("rate limit",1,true)or lw:find("429",1,true)or lw:find("resource_exhausted",1,true)or lw:find("resource exhausted",1,true)then return"quota"end if lw:find("api key not valid",1,true)or lw:find("api_key_invalid",1,true)or lw:find("key expired",1,true)or lw:find("permission denied",1,true)or lw:find("unauthenticated",1,true)or lw:find("invalid api key",1,true)or lw:find("403",1,true)or lw:find("401",1,true)then return"badkey"end if lw:find("high demand",1,true)or lw:find("overload",1,true)or lw:find("503",1,true)or lw:find("unavailable",1,true)or lw:find("temporarily",1,true)then return"busy"end if lw:find("not found",1,true)or lw:find("does not exist",1,true)or lw:find("404",1,true)then return"invalid_model"end if lw:find("mime",1,true)then return"mime"end return"api"end function XcCommand.once(rf,key,bodyTbl)local ok,en=pcall(function()return H:JSONEncode(bodyTbl)end)if not ok or not en then return nil,"json","encode failed"end local uw=BGE..AMI..":generateContent"local ok2,rsp=pcall(rf,{Url=uw,Method="POST",Headers={["Content-Type"]="application/json",["x-goog-api-key"]=tostring(key)},Body=en})if not ok2 then return nil,"http",tostring(rsp):sub(1,120)end if not rsp then return nil,"http","no response"end local rb=rsp.Body or rsp.body if rb==nil then rb=rsp end if type(rb)~="string"then local ok3,s=pcall(function()return H:JSONEncode(rb)end)rb=ok3 and s or tostring(rb)end if rb==""then return nil,"http","empty body HTTP "..tostring(rsp.StatusCode or rsp.Status or"?")end local dk,data=pcall(function()return H:JSONDecode(rb)end)if not dk or type(data)~="table"then return nil,"json",rb:sub(1,80)end if data.error then local m=data.error.message or data.error if type(m)~="string"then m=H:JSONEncode(m)end return nil,XcCommand.classify(m),tostring(m):sub(1,120)end if not data.candidates or#data.candidates==0 then if data.promptFeedback and data.promptFeedback.blockReason then return nil,"blocked","blocked:"..tostring(data.promptFeedback.blockReason)end return nil,"nochoices","no candidates"end local cd=data.candidates[1]if not cd.content or not cd.content.parts or#cd.content.parts==0 then local fr=cd.finishReason if fr and fr~="STOP"then return nil,"blocked","finish="..tostring(fr)end return nil,"nomsg","no parts"end local tx=nil for _,p in ipairs(cd.content.parts)do if p.text and p.text~=""and not p.thought then tx=(tx or"")..p.text end end if not tx or tx==""then return nil,"nomsg","empty text"end pcall(function()if data.usageMetadata and TU then local um=data.usageMetadata TU.prompt=(TU.prompt or 0)+(um.promptTokenCount or 0)TU.candidates=(TU.candidates or 0)+(um.candidatesTokenCount or 0)TU.total=(TU.total or 0)+(um.totalTokenCount or 0)TU.requests=(TU.requests or 0)+1 end end)return tx,nil,nil end function XcCommand.call(sys,user,mt,asJson)local rf=aiGetRequestFunc()if not rf then return nil,"nohttp","no request func"end local keys={BKey1,BKey2}local order={1,2}if XcCommand.keyIdx==2 and(os.clock()-(XcCommand.keySince or 0))<1200 then order={2,1}end local lastEt,lastEm="nokey","no key"for _,idx in ipairs(order)do local k=keys[idx]if k and k~=""then local wantJson=asJson local tries=0 while true do tries=tries+1 local gc={maxOutputTokens=mt or 600}if wantJson then gc.responseMimeType="application/json"end local body={contents={{role="user",parts={{text=sys.."\n\n"..user}}}},generationConfig=gc}local tx,et,em=XcCommand.once(rf,k,body)if tx then if idx~=XcCommand.keyIdx then XcCommand.keyIdx=idx XcCommand.keySince=os.clock()end return tx,nil,nil end lastEt,lastEm=et,em if et=="mime"and wantJson and tries<3 then wantJson=false elseif et=="busy"and tries<2 then task.wait(0.5)else break end end if not(lastEt=="quota"or lastEt=="badkey")then return nil,lastEt,lastEm end end end return nil,lastEt,lastEm end XcCommand_VERBS={}for w in("faster slower speed sprint fast slow higher freeze unfreeze follow following sit sitting stand jump jumping hide lead bam swordkill fling spam spamming walk walking run running go goto chase circle teleport tp come move wander explore patrol roam turn look face voidfollow escort say tell speak try attempt stay make create"):gmatch("%S+")do XcCommand_VERBS[w]=true end XcCommand_EXTRA={}for w in("spam spamming goto chase circle teleport tp repeat wander patrol roam turn hop random backward forward backwards sideways command"):gmatch("%S+")do XcCommand_EXTRA[w]=true end XcCommand_TIMING={}for w in("then after before until while every repeat repeatedly times again later once twice sec secs second seconds min mins minute minutes forever continuously keep whenever"):gmatch("%S+")do XcCommand_TIMING[w]=true end function XcCommand.isTask(text)local l=" "..tostring(text or""):lower().." "if l:find(" make me ",1,true)or l:find("script",1,true)or l:find("hack",1,true)or l:find(" for me ",1,true)then return false end local verbs,nv,extra,timing=0,0,false,false local seen={}for w in l:gmatch("[%a']+")do if XcCommand_VERBS[w]and not seen[w]then seen[w]=true nv=nv+1 end if XcCommand_EXTRA[w]then extra=true end if XcCommand_TIMING[w]then timin