t first: "..table.concat(list,"; ")..XcCommand.customList()end function XcCommand.parsePlan(txt)if not txt then return nil end local s=txt:gsub("```json",""):gsub("```","")local a=s:find("{",1,true)if not a then return nil end local b=nil for i=#s,a,-1 do if s:sub(i,i)=="}"then b=i break end end if not b then return nil end local ok,d=pcall(function()return H:JSONDecode(s:sub(a,b))end)if ok and type(d)=="table"then return d end return nil end function XcCommand.cleanChat(t)t=tostring(t or""):gsub("[%c]"," "):gsub("%s+"," ")t=t:gsub("^%s+",""):gsub("%s+$","")return t:sub(1,180)end function XcCommand.newScope(myId)local sc={alive=true,finished=false,conns={},insts={},threads={}}local ctx={}ctx.alive=function()return sc.alive and XcCommand.alive(myId)end ctx.finish=function()sc.finished=true end ctx.wait=function(t)task.wait(t or 0.03)return ctx.alive()end ctx.on=function(sig,fn)local c=sig:Connect(function(...)if ctx.alive()then fn(...)end end)sc.conns[#sc.conns+1]=c return c end ctx.new=function(cls,props,parent)local i=Instance.new(cls)if props then for k,v in pairs(props)do pcall(function()i[k]=v end)end end if parent then i.Parent=parent end sc.insts[#sc.insts+1]=i return i end ctx.spawn=function(fn,...)local th=task.spawn(function(...)pcall(fn,...)end,...)sc.threads[#sc.threads+1]=th return th end ctx.chat=function(m)sendChat(XcCommand.cleanChat(m))end ctx.player=pl ctx.hum=function()return hum()end ctx.hrp=function()return hrp()end ctx.find=function(n)return getPlayer(n)end ctx.hostPlayer=function()return getHost()end ctx.moveTo=function(pos)local h=hum()if h then pcall(function()h:MoveTo(pos)end)end end XcCommand.extendCtx(ctx,myId)sc.ctx=ctx sc.close=function()sc.alive=false for _,c in ipairs(sc.conns)do pcall(function()c:Disconnect()end)end for _,i in ipairs(sc.insts)do pcall(function()i:Destroy()end)end for _,t in ipairs(sc.threads)do pcall(function()task.cancel(t)end)end sc.conns,sc.insts,sc.threads={},{},{}end return sc end function XcCommand.cleanup()loca