playName)add("account age days",p.AccountAge)if p.Team then add("team",p.Team.Name)end else add("name",t.model.Name)end add("distance studs",math.floor(t.dist or 0))local h=ch and ch:FindFirstChildOfClass("Humanoid")if h then add("health",math.floor(h.Health).."/"..math.floor(h.MaxHealth))add("rig",XcVision.enumName(h.RigType))add("state",h.Sit and"sitting"or(h.MoveDirection.Magnitude>0.1 and"moving"or"standing still"))end if ch then local tool=ch:FindFirstChildOfClass("Tool")add("holding",tool and tool.Name)local acc={}for _,c in ipairs(ch:GetChildren())do if c:IsA("Accessory")and#acc<8 then acc[#acc+1]=c.Name end end if#acc>0 then add("accessories",table.concat(acc,", "))end local bc=ch:FindFirstChildOfClass("BodyColors")if bc then add("skin tone",XcVision.cname(bc.TorsoColor3))end add("shirt",ch:FindFirstChildOfClass("Shirt")and"yes")add("pants",ch:FindFirstChildOfClass("Pants")and"yes")add("graphic tee",ch:FindFirstChildOfClass("ShirtGraphic")and"yes")end else local i=t.inst add("type","object")add("name",i.Name)add("class",i.ClassName)local mdl=i:FindFirstAncestorOfClass("Model")if mdl and mdl~=i and mdl~=W then add("part of model",mdl.Name)end local chain,cur={},i.Parent while cur and cur~=W and#chain<3 do chain[#chain+1]=cur.Name cur=cur.Parent end if#chain>0 then add("inside",table.concat(chain," < "))end if i:IsA("BasePart")then add("material",XcVision.enumName(i.Material))add("color",XcVision.cname(i.Color))add("size studs",string.format("%.0fx%.0fx%.0f",i.Size.X,i.Size.Y,i.Size.Z))add("anchored",i.Anchored and"yes"or"no")if i.Transparency>0 then add("transparency",string.format("%.1f",i.Transparency))end add("solid",i.CanCollide and"yes"or"no")end if i:IsA("MeshPart")then add("shape","custom mesh")end if i:IsA("Terrain")and t.hit then add("terrain material",XcVision.enumName(t.hit.Material))end local root=(mdl and mdl~=W)and mdl or i local texts,extra,n={},{},0 local ok,desc=pcall(function()return root:GetDescendants()end)if ok then for _,d in ipairs(desc