and.takeover(keepSit)if S.hidden then pcall(doSpawn)end if S.mode~="XcCommand"then pcall(stopAllModes)S.mode="XcCommand" S.waypoints=nil S.cachedPath=nil S.lastMovePos=nil S.committedTarget=nil S.stableFollowDir=nil end local h=hum()if h and not keepSit then if h.Sit or S.sitting then S.sitting=false pcall(function()h.Sit=false h:ChangeState(Enum.HumanoidStateType.GettingUp)end)task.wait(0.1)end pcall(function()if h.WalkSpeed<=0 then h.WalkSpeed=BS end if h.JumpPower<=0 then h.JumpPower=BJ end h.PlatformStand=false end)end return h end function XcCommand.flat(v)local f=Vector3.new(v.X,0,v.Z)if f.Magnitude<0.01 then return nil end return f.Unit end function XcCommand.pool(used)local host=getHost()local t={}for _,p in ipairs(P:GetPlayers())do if p~=pl and p~=host and getPlayerHRP(p)and not(used and used[p])then t[#t+1]=p end end return t end function XcCommand.pickPlayer(who,used)who=trim(tostring(who or"")):lower()local host=getHost()if who==""or who=="boss"or who=="me"or who=="host"or who=="owner"then return host end if who=="random"or who=="any"or who=="anyone"or who=="anybody"or who=="someone"then local t=XcCommand.pool(used)if#t==0 and used then for k in pairs(used)do used[k]=nil end t=XcCommand.pool(nil)end if#t==0 then return nil end return t[math.random(1,#t)]end if who=="nearest"or who=="closest"then local r=hrp()if not r then return nil end local best,bd=nil,1e9 for _,p in ipairs(XcCommand.pool(nil))do local tr=getPlayerHRP(p)local d=(tr.Position-r.Position).Magnitude if d<bd then best,bd=p,d end end return best end local p=getPlayer(who)if p==pl then return nil end return p end function XcCommand.tpTo(p,off)local r,tr=hrp(),getPlayerHRP(p)if not r or not tr then return false end if isInVoid(tr.Position)then return false end if p==getHost()then teleportToHost()return true end off=off or Vector3.new(0,0,4)local pos=(tr.CFrame*CFrame.new(off.X,0,off.Z)).Position+Vector3.new(0,3,0)pcall(function()r.CFrame=CFrame.new(pos,Vector3.new(tr.Position.X,pos.Y,tr.Positi