m~=""then lines[1]=m end end if#lines>0 then local n=math.clamp(math.floor(tonumber(st.n)or#lines),1,15)local d=math.clamp(tonumber(st.d)or 2.5,1.5,10)for k=1,n do if not alive()then return false end XC_RAW=true pcall(sendChat,lines[((k-1)%#lines)+1])XC_RAW=false if k<n and not XcCommand.sleep(myId,d)then return false end end end return true elseif t=="code"or t=="xcode"then local req=trim(tostring(st.req or st.q or""))if req~=""then ctx.transient=true XcCommand.takeover()local code,secs=XcCommand.runCode(req,st.s,myId)local nm=tostring(st.save or"")if code and nm~=""and alive()then XcCommand.registerCustom(nm,req,code,secs)end end return alive()elseif t=="ask"then local q=trim(tostring(st.q or""))if q~=""then local n=tick()if n-LRT<RCL then if not XcCommand.sleep(myId,RCL-(n-LRT)+0.15)then return false end end if alive()then XcCommand.askNow(q,myId)return alive()end end return alive()end ctx.transient=true if t=="tp"then local p=XcCommand.pickPlayer(st.who)if not p then sendChat(pick(R_.notfound))return true end XcCommand.takeover()XcCommand.tpTo(p,Vector3.new(0,0,4))return XcCommand.sleep(myId,0.1)elseif t=="tprandom"then local n=math.clamp(math.floor(tonumber(st.n)or 5),1,25)local d=math.clamp(tonumber(st.d)or 0.4,0.15,5)local used={}for k=1,n do if not alive()then return false end XcCommand.takeover()local p=XcCommand.pickPlayer("random",used)if not p then sendChat(pick(R_.norandom))break end used[p]=true XcCommand.tpTo(p,Vector3.new(0,0,4))if not XcCommand.sleep(myId,d)then return false end end if st.back==true or st.back=="true"then local host=getHost()if host then XcCommand.takeover()XcCommand.tpTo(host)end end return XcCommand.sleep(myId,0.1)elseif t=="goto"then local p=XcCommand.pickPlayer(st.who or"boss")if not p then sendChat(pick(R_.notfound))return true end XcCommand.takeover()XcCommand.goToPlayer(p,myId,st.s,st.tp~=false)return XcCommand.sleep(myId,0.1)elseif t=="walk"then if(tonumber(st.s)or 0)>0 then XcCommand.walkFor(st.dir or"forward",st.s,myId)ret