yer(st.who or"boss")XcCommand.takeover()if p then FX_FACE(p)end return XcCommand.sleep(myId,0.1)elseif t=="jump"then local n=math.clamp(math.floor(tonumber(st.n)or 1),1,30)local d=math.clamp(tonumber(st.d)or 0.6,0.3,3)for k=1,n do if not alive()then return false end local h=XcCommand.takeover()if h then pcall(function()h.Jump=true h:ChangeState(Enum.HumanoidStateType.Jumping)end)end if not XcCommand.sleep(myId,d)then return false end end return alive()elseif t=="sit"then local h=XcCommand.takeover(true)S.sitting=true if h then pcall(function()h.WalkSpeed=0 h.JumpPower=0 h.Sit=true h:ChangeState(Enum.HumanoidStateType.Seated)end)end local secs=tonumber(st.s)or 0 if secs>0 then if not XcCommand.sleep(myId,math.clamp(secs,0.5,120))then return false end XcCommand.takeover()else ctx.persist=true return XcCommand.sleep(myId,0.15)end return alive()elseif t=="stand"then XcCommand.takeover()return XcCommand.sleep(myId,0.1)elseif t=="emote"then local e=tostring(st.e or"wave"):lower()if not XcCommand.EMOTES[e]then e="wave"end XcCommand.takeover()sendChat("/e "..e)return XcCommand.sleep(myId,math.clamp(tonumber(st.d)or 1.8,0.5,10))elseif t=="speed"then local v=math.clamp(tonumber(st.v)or 16,4,150)BS=v local h=XcCommand.takeover()if h then pcall(function()h.WalkSpeed=BS end)end return XcCommand.sleep(myId,0.05)elseif t=="follow"then local p=XcCommand.pickPlayer(st.who or"boss")if not p then sendChat(pick(R_.notfound))return true end XcCommand.takeover()XcCommand.followPlayer(p,st.s,myId)return alive()elseif t=="circle"then local p=XcCommand.pickPlayer(st.who or"boss")if not p then sendChat(pick(R_.notfound))return true end XcCommand.takeover()XcCommand.circlePlayer(p,st.s,st.r,myId)return alive()end return true end function XcCommand.execute(plan,myId)local steps=plan.steps if type(steps)~="table"then steps={}end local ctx={count=0,started=os.clock(),transient=false,persist=false}for i,st in ipairs(steps)do if i>40 then break end local okS,resS=pcall(XcCommand.step,st,myId,ctx,0)if not okS then XcCommand.log("[XcCommand] step error: "..tostring(resS):sub(1,80),C.red)elseif not resS then break end end if not XcCommand.alive(myId)then return end XcCommand.active=false XcCommand.cleanup()if ctx.transient and not ctx.persist and(S.mode~="Follow"or S.sitting)then pcall(stopAllModes)end if not ctx.persist then pcall(XcVoid.resume)end if os.clock()-ctx.started>15 then local dn=XcCommand.cleanChat(plan.done)if dn==""then dn="Complete."end sendChat(dn)end end function XcCommand.run(prompt)if ROLE~="BOT"or antiBan.detected then return end if(not BKey1 or BKey1=="")and(not BKey2 or BKey2=="")then sendChat("no XcCommand key set")return end local now=os.clock()if now-XcCommand.lastReq<0.5 then return end XcCommand.lastReq=now XcCommand.cancel()XcCommand.id=XcCommand.id+1 local myId=XcCommand.id XcCommand.active=true sendChat(pick({"on it","one sec"}))local user="BOSS REQUEST: "..prompt.."\n\n"..XcCommand.context()local rp,et,em=XcCommand.call(XcCommand_SYS,user,1400,true)if not XcCommand.alive(myId)then return end if not rp then XcCommand.active=false XcCommand.fail(et,em)return end local plan=XcCommand.parsePlan(rp)if not plan then local rp2=XcCommand.call(XcCommand_SYS,user.."\nREMINDER: reply with the JSON object only, nothing else.",1400,true)if not XcCommand.alive(myId)then return end if rp2 then plan=XcCommand.parsePlan(rp2)end end if not plan or type(plan.steps)~="table"or#plan.steps==0 then XcCommand.log("[XcCommand] no plan, escalating to Xcode",C.green)plan={steps={{t="xcode",req=prompt,s=25}}}end local say=XcCommand.cleanChat(plan.say)XcCommand.log("[XcCommand] task: "..prompt:sub(1,60),C.green)XcCommand.execute(plan,myId)end function XcCommand.route(prompt)local p=trim(tostring(prompt or""))local forced=false local fp=p:match("^[Tt][Aa][Ss][Kk][%s:]+(.+)$")if fp then p=trim(fp)forced=true end if p==""then return false end local lp=XcCommand.localPlan(p)if lp then if ROLE=="BOT"then task.spawn(function()XcCommand.runLocal(lp)end)end return true end if not forced then local ql=p:lower()if(ql:match("^what ")or ql:match("^who ")or ql:match("^when ")or ql:match("^where ")or ql:match("^why ")or ql:match("^how ")or ql:match("^is ")or ql:match("^are ")or ql:match("^do ")or ql:match("^does ")or ql:match("^can ")or ql:match("^could ")or ql:match("^tell me "))and not(ql:find("make")or ql:find("script")or ql:find("hack")or ql:find("spam")or ql:find("repeat")or ql:find("command")or ql:find("for me")or ql:find("build")or ql:find("create"))then return false end end if not forced then local tl=p:lower()if not(tl:find("make")or tl:find("script")or tl:find("hack")or tl:find("for me")or tl:find("build")or tl:find("create")or tl:find("command")or tl:find("spam")or tl:find("repeat")or tl:find(" then ")or tl:find(" after ")or tl:find(" until ")or tl:find(" while ")or tl:find(" every ")or tl:find("forever")or tl:find("continuously")or tl:find("keep ")or tl:find("task"))then return false end end if not forced and not XcCommand.isTask(p)then return false end if not forced and XcFast and XcFast.chatLike(p)then return false end if ROLE=="BOT"then task.spawn(function()XcCommand.run(p)end)else XcCommand.log("[XcCommand] task sent to bot: "..p:sub(1,50),C.green)end return true end function XcCommand.hook(text)if ROLE=="BOT"and XcVoid.hookPhrase(text)then return true end if not XcCommand.active or ROLE~="BOT" then return false end if XcCommand.isStop(text)then XcCommand.stop()return true end local l=tostring(text or""):lower()local nm=l:match("^!(%S+)")if nm and nm~="ask"and nm~="info"and AI_CMD_WHITELIST[nm]then XcCommand.cancel()end return false end XC_THINK_TRY={'{"thinkingLevel":"minimal"}','{"thinkingBudget":0}',false}XC_THINK_I=1 XC_THINKW={}function XcThink(r)if not r then return r end if XC_THINKW[r]then return XC_THINKW[r]end local w=function(req)if type(req)~="table"or type(req.Body)~="string"or not tostring(req.Url or""):find(":generateContent",1,true)then return r(req)end local rsp for attempt=1,3 do local v=XC_THINK_TR