 or 10,r=8}}end return nil end if verb=="follow"then local nm=XcCommand.nameIn(c)if nm then return{{t="follow",who=nm,s=secs or 15}}end return nil end local sp=c:match("^set speed to (%d+)")or c:match("^speed (%d+)")or c:match("^walkspeed (%d+)")if sp then return{{t="speed",v=tonumber(sp)}}end if verb and XcCommand.LOCALCMD[verb]then local rest=trim(c:sub(#verb+1))local arg="" if verb=="bam"or verb=="fling"or verb=="swordkill"or verb=="lead"or verb=="escort"then local nm=(rest:find("random",1,true)and"random")or XcCommand.nameIn(rest)if not nm then return nil end arg=nm elseif verb=="backoff"or verb=="getcloser"then arg=tostring(tonumber(rest:match("%d+"))or"")end local out={{t="cmd",c=trim(verb.." "..arg)}}if secs and XcCommand.STOPPER[verb]then out[#out+1]={t="wait",s=secs}out[#out+1]={t="cmd",c=XcCommand.STOPPER[verb]}end return out end return nil end function XcCommand.localPlan(text)local o=tostring(text or"")if#o>300 then return nil end if o:find('"',1,true)and not o:lower():match("^%s*say ")then return nil end
