ip","fly","flying","infinite jump","inf jump","speed hack","speedhack","god mode","godmode","kill aura","killaura","auto farm","autofarm","walkspeed","walk speed","jump power","jumppower","lua code","luau","executor","gui","auto clicker","autoclicker","anti afk","fullbright","full bright","xray","wallhack","wall hack","invisible","click tp","clicktp","btools"}XcCode.MAKE={"make me","give me","let me","i want","i wanna","i need","can you make","could you make","create","write","generate","build me","code me","code a","code an","code for","make a","make an"}XcCode.ABIL={"sit","jump","run","fast","faster","invisible","teleport","tp","fly","noclip","walk through","see through","bigger","smaller","tall","spin","float","glow","rainbow","speed","strong","immortal","invincible","unkillable","higher","stuck","freeze"}XcCode.QUESTION={"what","who","why","when","where","how","which","is","are","do","does","did","tell","explain","describe","define","whats","hows"}function XcCode.has(l,k)return l:find("%f[%a]"..k.."s?%f[%A]")~=nil end function XcCode.classify(text)local l=tostring(text or""):lower()l=l:gsub("[%?!%.,]"," ")l=l:gsub("%s+"," ")l=trim(l)if l==""then return"no"end if l:find("command",1,true)then return"no"end local first=l:match("^(%a+)")local strong,make,abil=false,false,false for _,k in ipairs(XcCode.STRONG)do if XcCode.has(l,k)then strong=true break end end for _,k in ipairs(XcCode.MAKE)do if l:find(k,1,true)then make=true break end end for _,k in ipairs(XcCode.ABIL)do if XcCode.has(l,k)then abil=true break end end local isQ=false for _,k in ipairs(XcCode.QUESTION)do if first==k then isQ=true break end end if isQ and not make then return"no"end if strong and make then return"yes"end if l:find("^script ")or l:find("^give me a script")or l:find("^make me a script")then return"yes"end if(l:find("^make me ")or l:find("^give me ")or l:find("^let me "))and abil then return"yes"end if strong or make then return"maybe"end return"no" end function XcCode.route(prompt)local 